<script>
(()=>{const root=document.getElementById(<?= json_encode($ocrRootId, JSON_HEX_TAG) ?>);if(!root||root.dataset.booted==='1')return;root.dataset.booted='1';const OCR_API_BASE=<?= json_encode($ocrApiBase, JSON_HEX_TAG) ?>;const tr=<?= json_encode($ocrT,JSON_UNESCAPED_UNICODE | JSON_HEX_TAG) ?>;const q=role=>root.querySelector(`[data-ocr-role="${role}"]`);const qa=selector=>Array.from(root.querySelectorAll(selector));const MAX_PHOTOS=10;const state={step:1,items:[],jobId:'',pollTimer:null,report:null,stores:[],mappings:{},selection:{},skipped:new Set(),createRaw:'',finalizing:false,canceling:false,dateChoices:{}};const photosInput=q('photos-input');const dropzone=q('dropzone');const uploadPreviews=q('upload-previews');const uploadContinue=q('upload-continue');const resolveList=q('resolve-list');const resolveEmpty=q('resolve-empty');const scanWarningsWrap=q('scan-warnings-wrap');const scanWarnings=q('scan-warnings');const createStoreModal=q('create-store-modal');const createStoreInput=q('create-store-input');let pollFailures=0;function tp(s,m){if(!s)return'';let out=s;Object.keys(m||{}).forEach(k=>{out=out.split('{'+k+'}').join(String(m[k]??''));});return out;}function friendlyHttpError(text){const t=String(text||'');const m=t.match(/<title>([^<]*)<\/title>/i);const code=t.match(/\b(\d{3})\s+(?:Bad Gateway|Gateway Time-out|Service Unavailable|Internal Server Error|Not Found)/i);const label=(code&&code[1])||(m&&m[1])||'';return label?('server_error_'+label):(t.slice(0,160)||tr.error);}function escHtml(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}function icon(name){const icons={plus:'<svg class="ocrw-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14"/><path d="M5 12h14"/></svg>',trash:'<svg class="ocrw-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v5"/><path d="M14 11v5"/></svg>'};return icons[name]||'';}function apiUrl(query=''){return `${OCR_API_BASE}${query}`;}function emitProgress(lines){if(typeof window.handleEmbeddedOCRProgress==='function')window.handleEmbeddedOCRProgress(lines);if(window.parent&&window.parent!==window)window.parent.postMessage({type:'ocr_progress',lines},'*');}function emitFinished(message){if(typeof window.handleEmbeddedOCRFinished==='function')window.handleEmbeddedOCRFinished(message,state.report||null);if(window.parent&&window.parent!==window)window.parent.postMessage({type:'ocr_finished',message},'*');}function heroTextByStep(step){const map={1:tr.hero_idle,2:tr.hero_scan,3:tr.hero_resolve,4:tr.hero_report};return map[step]||tr.hero_idle;}function setHeroStatus(text){q('hero-status').textContent=text;}function pulseHeroStatus(text){setHeroStatus(text);window.clearTimeout(pulseHeroStatus.timer);pulseHeroStatus.timer=window.setTimeout(()=>setHeroStatus(heroTextByStep(state.step)),1800);}function formatWarn(w){if(typeof w==='string')return w;if(!w||!w.code)return JSON.stringify(w);if(w.code==='no_rates')return tr.warn_no_rates||'';if(w.code==='skip_no_rate')return tp(tr.warn_skip_no_rate||'',{merchant:w.merchant||'',currency:w.currency||'',amount:w.amount||''});if(w.code==='no_amount_in_file')return tp(tr.warn_no_amount_in_file||'',{file:w.file||''});if(w.code==='file_error')return tp(tr.warn_file_error||'',{file:w.file||'',message:w.message||''});if(w.code==='already_imported')return tp(tr.warn_already_imported||'',{date:w.date||'',store:w.store||'',amount:w.amount||''});return JSON.stringify(w);}function setStep(step){state.step=step;qa('.ocrw-panel').forEach(panel=>panel.classList.toggle('is-active',Number(panel.dataset.ocrPanel)===step));qa('.ocrw-step').forEach(node=>{const value=Number(node.dataset.ocrStep);node.classList.toggle('is-active',value===step);node.classList.toggle('is-done',value<step);const num=node.querySelector('.ocrw-step-num');if(num)num.textContent=value<step?'✓':String(value);});const roadmap=root.querySelector('.ocrw-roadmap');if(roadmap)roadmap.classList.toggle('is-live',step===2);setHeroStatus(heroTextByStep(step));}function revokeStateUrls(){state.items.forEach(item=>{if(item.url)URL.revokeObjectURL(item.url);});}function ensureItems(list){revokeStateUrls();state.items=[...list].slice(0,MAX_PHOTOS).filter(file=>String(file.type||'').startsWith('image/')).map((file,index)=>({id:`item-${index}-${Date.now()}`,file,name:file.name||`${tr.photo} ${index+1}`,url:URL.createObjectURL(file)}));renderUploadStep();}function previewUrl(item){return item.url;}function renderUploadStep(){q('upload-count-badge').textContent=String(state.items.length);uploadContinue.disabled=!state.items.length;uploadPreviews.innerHTML=state.items.length?state.items.map((item,index)=>`<div class="ocrw-preview-card"><span class="ocrw-preview-tag">${escHtml(tr.photo+' '+(index+1))}</span><img src="${escHtml(previewUrl(item))}" alt="${escHtml(item.name)}"><div class="ocrw-preview-meta"><span>${escHtml(item.name)}</span><span>${index+1}</span></div><button type="button" class="ocrw-preview-delete" data-delete-index="${index}" title="${escHtml(tr.delete||'Delete')}">${icon('trash')}</button></div>`).join(''):`<div class="ocrw-empty" style="grid-column:1/-1;">${escHtml(tr.no_files)}</div>`;}async function api(query,options={}){const controller=('AbortController'in window)?new AbortController():null;const timeoutMs=(options&&options.timeoutMs)||20000;const timer=controller?window.setTimeout(()=>controller.abort(),timeoutMs):null;try{const response=await fetch(apiUrl(query),{...(options||{}),signal:controller?controller.signal:(options&&options.signal)});const text=await response.text();if(!text){throw new Error(tr.error||'Empty response');}try{return JSON.parse(text);}catch(e){throw new Error(friendlyHttpError(text));}}catch(error){if(error&&error.name==='AbortError')throw new Error('request_timeout');throw error;}finally{if(timer)window.clearTimeout(timer);}}async function loadStores(){const data=await api('?api=stores');state.stores=Array.isArray(data.stores)?data.stores:[];state.mappings=data.mappings&&typeof data.mappings==='object'?data.mappings:{};}function storeName(store){return typeof store==='string'?store:String(store&&store.name||'');}function storePhoto(store){return typeof store==='object'&&store?String(store.photo||''):'';}function storeByName(name){return state.stores.find(store=>storeName(store)===name)||null;}function storeAvatar(store){const photo=storePhoto(store);const name=storeName(store);return photo?`<img class="ocrw-store-photo" src="${escHtml(photo)}" alt="${escHtml(name)}">`:`<span class="ocrw-store-fallback">${escHtml((name||'?').slice(0,1).toUpperCase())}</span>`;}function chooseStore(raw,name){state.selection[raw]=name;renderResolveStep();}function closeStorePickers(){qa('.ocrw-store-picker.is-open').forEach(node=>node.classList.remove('is-open'));}function renderWarningList(target,list){target.innerHTML=(list||[]).length?(list||[]).map(item=>`<div class="ocrw-warn-item">${escHtml(formatWarn(item))}</div>`).join(''):`<div class="ocrw-empty">${escHtml(tr.empty_warnings)}</div>`;}function perFileProgress(job,progress){const processed=Number(progress.processed||0);const total=Math.max(Number(progress.total||0),state.items.length);const pct=Number(progress.percent||0);const rows=(job&&job.records)||[];const done=new Set();(rows||[]).forEach(row=>{const src=String(row.source_file||row.file_name||row.file||'').trim();if(src)done.add(src);});return state.items.map((item,index)=>{const isCurrent=processed<total&&index===Math.min(processed,total-1);const isDone=index<processed||done.has(item.name);const filePct=isDone?100:(isCurrent?Math.max(5,Math.min(95,pct)):0);return {name:item.name,pct:filePct,state:isDone?'done':(isCurrent?'active':'pending')};});}function renderFileProgress(list){const wrap=q('file-progress-list');if(!wrap)return;wrap.innerHTML=(list||[]).map(entry=>`<div class="ocrw-file-item is-${entry.state}"><div class="ocrw-file-thumb">🧾</div><div class="ocrw-file-info"><div class="ocrw-file-name">${escHtml(entry.name)}</div><div class="ocrw-file-bar"><span style="width:${Math.round(entry.pct)}%;"></span></div></div><div class="ocrw-file-pct">${entry.state==='done'?'✓':'~'+Math.round(entry.pct)+'%'}</div></div>`).join('');}function setRecognitionStats(job){const progress=job.progress||{total:0,processed:0,percent:0};const rows=job.records||[];const recognized=job.recognized||rows;q('scan-total').textContent=String(progress.total||0);q('scan-processed').textContent=String(progress.processed||0);q('scan-records').textContent=String(rows.length||recognized.length);q('scan-unresolved').textContent=String((job.unresolved||[]).length);q('scan-currency').textContent=`${tr.currency}: ${job.base_currency||'—'}`;q('progress-fill').style.width=`${progress.percent||0}%`;q('progress-percent').textContent=`${Math.round(progress.percent||0)}%`;const phase=job.phase||job.state||"";let progressText=tp(tr.processing_line||tr.progress_line,{cur:progress.processed||0,total:progress.total||0,pct:progress.percent||0});if(phase==="queued")progressText=tp(tr.queued_line||tr.progress_line,{pos:job.queue_position||1,cur:progress.processed||0,total:progress.total||0,pct:progress.percent||0});q('progress-text').textContent=progressText;renderFileProgress(perFileProgress(job,progress));scanWarningsWrap.classList.toggle('ocrw-hidden',!(job.warnings||[]).length);renderWarningList(scanWarnings,job.warnings||[]);}function dateUnresolvedRows(){const map=new Map();const collect=row=>{if(!row||!row.date_unresolved||!row.ocr_row_id)return;const key=String(row.ocr_row_id);if(!map.has(key))map.set(key,{rowId:key,store:row.store||row.merchant_raw||'',date:row.date||'',amount:Number(row.amount||0),currency:row.currency||''});};(state.report&&state.report.records||[]).forEach(collect);(state.report&&state.report.unresolved||[]).forEach(collect);return [...map.values()];}function renderDatePick(){const rows=dateUnresolvedRows();state.dateChoices=state.dateChoices||{};rows.forEach(row=>{if(!state.dateChoices[row.rowId])state.dateChoices[row.rowId]=row.date;});const wrap=q('date-pick-wrap');const list=q('date-pick-list');q('date-pick-count-badge').textContent=String(rows.length);wrap.classList.toggle('ocrw-hidden',!rows.length);if(!rows.length){list.innerHTML='';return;}list.innerHTML=rows.map(row=>`<div class="ocrw-resolve-line"><span><strong>${escHtml(row.store)}</strong> <span class="ocrw-note">${escHtml(Number(row.amount||0).toFixed(2))} ${escHtml(row.currency)}</span></span><input type="date" class="ocrw-field" style="max-width:180px;" data-date-input="${escHtml(row.rowId)}" value="${escHtml(state.dateChoices[row.rowId]||row.date)}" aria-label="${escHtml(tr.choose_date)}"></div>`).join('');qa('[data-date-input]').forEach(input=>input.onchange=()=>{state.dateChoices[input.dataset.dateInput]=input.value;});}async function saveDates(){const dates=state.dateChoices||{};if(!Object.keys(dates).length){renderReport();setStep(4);return;}try{const data=await api('?api=set_dates',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:state.jobId,dates})});if(data.status!=='ok'){pulseHeroStatus(tp(tr.err_start,{message:data.message||tr.error}));return;}pulseHeroStatus(tp(tr.dates_saved,{count:data.updated||0}));const status=await api(`?api=status&job_id=${encodeURIComponent(state.jobId)}`);if(status.status==='ok')state.report=status.job||state.report;state.dateChoices={};renderDatePick();renderReport();setStep(4);}catch(error){pulseHeroStatus(tp(tr.err_start,{message:error.message||tr.error}));}}function unresolvedSummaryRows(rows){const map=new Map();(rows||[]).forEach(item=>{const raw=String(item&&item.merchant_raw||'').trim();if(!raw||state.skipped.has(raw))return;if(!map.has(raw)){map.set(raw,{raw,count:0,suggested:item.suggested_store||'',confidence:item.confidence||0,items:[]});}const row=map.get(raw);row.count+=1;row.items.push(item);if(!row.suggested&&item.suggested_store)row.suggested=item.suggested_store;row.confidence=Math.max(Number(row.confidence||0),Number(item.confidence||0));});return [...map.values()];}function renderResolveStep(){const rows=unresolvedSummaryRows(state.report&&state.report.unresolved||[]);rows.forEach(row=>{if(!state.selection[row.raw]&&state.mappings[row.raw])state.selection[row.raw]=state.mappings[row.raw];});q('resolve-count-badge').textContent=String(rows.length);resolveList.innerHTML='';resolveEmpty.classList.toggle('ocrw-hidden',rows.length>0);if(!rows.length)return;resolveList.innerHTML=rows.map(row=>{const selected=state.selection[row.raw]||'';const selectedStore=storeByName(selected);const details=row.items.map(item=>`<div class="ocrw-resolve-line"><span>${escHtml(item.date||'')}</span><strong>${escHtml(Number(item.amount||0).toFixed(2))} ${escHtml(item.currency||'')}</strong></div>`).join('');const options=state.stores.map(store=>{const name=storeName(store);return `<button type="button" class="ocrw-store-option${name===selected?' is-selected':''}" data-store-option="${escHtml(row.raw)}" data-store-name="${escHtml(name)}">${storeAvatar(store)}<span>${escHtml(name)}</span></button>`;}).join('');return `<div class="ocrw-resolve-row"><div class="ocrw-resolve-main"><div class="ocrw-resolve-raw">${escHtml(row.raw)}</div><div class="ocrw-resolve-sub"><span>${escHtml(tr.occurrences)}: ${row.count}</span>${row.suggested?`<span>${escHtml(tr.suggested)}: ${escHtml(row.suggested)}</span>`:''}${row.confidence?`<span>${Math.round(row.confidence*100)}%</span>`:''}</div><div class="ocrw-resolve-lines">${details}</div></div><div class="ocrw-resolve-actions"><div class="ocrw-store-picker" data-picker="${escHtml(row.raw)}"><button type="button" class="ocrw-store-trigger" data-store-trigger="${escHtml(row.raw)}">${selectedStore?storeAvatar(selectedStore):'<span class="ocrw-store-fallback">?</span>'}<span>${escHtml(selected||tr.choose_store)}</span></button><div class="ocrw-store-menu">${options}</div></div><button type="button" class="ocrw-btn ocrw-btn-secondary" data-create-raw="${escHtml(row.raw)}" data-create-name="${escHtml(row.suggested||row.raw)}">${icon('plus')}${escHtml(tr.create_store)}</button><button type="button" class="ocrw-btn ocrw-btn-danger" data-delete-raw="${escHtml(row.raw)}" title="${escHtml(tr.delete)}" aria-label="${escHtml(tr.delete)}">${icon('trash')}<span class="ocrw-sr">${escHtml(tr.delete)}</span></button></div></div>`;}).join('');qa('[data-store-trigger]').forEach(button=>button.onclick=event=>{event.stopPropagation();const wrap=button.closest('.ocrw-store-picker');const open=wrap.classList.contains('is-open');closeStorePickers();wrap.classList.toggle('is-open',!open);});qa('[data-store-option]').forEach(button=>button.onclick=event=>{event.stopPropagation();chooseStore(button.dataset.storeOption,button.dataset.storeName);closeStorePickers();});qa('[data-delete-raw]').forEach(button=>button.onclick=()=>{state.skipped.add(button.dataset.deleteRaw);delete state.selection[button.dataset.deleteRaw];renderResolveStep();});qa('[data-create-raw]').forEach(button=>button.onclick=()=>openCreateStore(button.dataset.createRaw,button.dataset.createName||button.dataset.createRaw));}function renderReport(){const job=state.report||{};const records=job.records||[];const warnings=job.warnings||[];const manualAdded=Number(job.manual_added||0);const unresolved=Number((job.unresolved||[]).length);const addedCount=Number(job.added_count||records.filter(row=>row.status==='added').length);q('report-currency').textContent=`${tr.currency}: ${job.base_currency||'—'}`;q('report-auto').textContent=String(addedCount);q('report-manual').textContent=String(manualAdded);q('report-remaining').textContent=String(unresolved);renderWarningList(q('report-warnings'),warnings);const hasRows=records.length>0;q('report-empty').classList.toggle('ocrw-hidden',hasRows);q('report-table-wrap').classList.toggle('ocrw-hidden',!hasRows);q('report-tbody').innerHTML=records.map(row=>{const badge=row.status==='duplicate'?` <span class="ocrw-note">${escHtml(tr.report_duplicate||'already imported')}</span>`:'';return `<tr><td>${escHtml(row.date||'')}</td><td>${escHtml(row.store||'')}${badge}</td><td>${escHtml(Number(row.amount||0).toFixed(2))} ${escHtml(job.base_currency||'')}</td></tr>`;}).join('');}async function startRecognition(){if(!state.items.length){setStep(1);return;}setStep(2);const fd=new FormData();q('progress-fill').style.width='0%';q('progress-percent').textContent='0%';q('progress-text').textContent=tr.loading;scanWarningsWrap.classList.add('ocrw-hidden');scanWarnings.innerHTML='';state.startWatchdog=window.setTimeout(()=>{if(!state.jobId){q('progress-text').textContent=tp(tr.err_start,{message:'request_timeout'});emitProgress([tp(tr.err_start,{message:'request_timeout'})]);resetFlow(tp(tr.err_start,{message:'request_timeout'}));}},150000);try{for(let index=0;index<state.items.length;index++){const item=state.items[index];fd.append('photos[]',item.file,item.file.name||('photo-'+(index+1)+'.jpg'));}const data=await api('?api=start',{method:'POST',body:fd,timeoutMs:120000});if(data.status!=='ok'){window.clearTimeout(state.startWatchdog);q('progress-text').textContent=tp(tr.err_start,{message:data.message||tr.error});emitProgress([tp(tr.err_start,{message:data.message||tr.error})]);return;}state.jobId=data.job_id||'';window.clearTimeout(state.startWatchdog);q('scan-currency').textContent=`${tr.currency}: ${data.base_currency||'—'}`;emitProgress([tr.processing_title,`${tr.currency}: ${data.base_currency||'—'}`]);pollJob(state.jobId);}catch(error){window.clearTimeout(state.startWatchdog);q('progress-text').textContent=tp(tr.err_start,{message:error.message||tr.error});emitProgress([tp(tr.err_start,{message:error.message||tr.error})]);}}function stopPolling(){if(state.pollTimer){clearInterval(state.pollTimer);state.pollTimer=null;}}function resetFlow(message){stopPolling();state.jobId='';state.report=null;state.selection={};state.skipped=new Set();state.finalizing=false;state.canceling=false;state.dateChoices={};state.mappings={};q('progress-fill').style.width='0%';q('progress-percent').textContent='0%';q('progress-text').textContent=message||tr.loading;renderFileProgress([]);scanWarningsWrap.classList.add('ocrw-hidden');scanWarnings.innerHTML='';resolveList.innerHTML='';resolveEmpty.classList.add('ocrw-hidden');q('resolve-count-badge').textContent='0';q('report-tbody').innerHTML='';q('report-warnings').innerHTML='';revokeStateUrls();state.items=[];photosInput.value='';setStep(1);renderUploadStep();}function finishRecognition(job){state.report=job;stopPolling();renderDatePick();if((job.unresolved||[]).length){renderResolveStep();setStep(3);return;}if(dateUnresolvedRows().length){setStep(3);return;}renderReport();setStep(4);}async function pollJob(jobId){stopPolling();const tick=async()=>{try{const data=await api(`?api=status&job_id=${encodeURIComponent(jobId)}`);pollFailures=0;if(data.status!=='ok'){q('progress-text').textContent=tr.status_error;return;}const job=data.job||{};state.report=job;setRecognitionStats(job);emitProgress([q('progress-text').textContent,...(job.warnings||[]).map(formatWarn)]);if(job.state==='done'){finishRecognition(job);}if(job.state==='canceled'){resetFlow(tr.cancel_done);emitProgress([tr.cancel_done]);return;}if(job.state==='error'){stopPolling();q('progress-text').textContent=tp(tr.err_worker,{message:job.message||tr.error});emitProgress([tp(tr.err_worker,{message:job.message||tr.error})]);await api('?api=finalize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:state.jobId})}).catch(()=>{});resetFlow(tp(tr.err_worker,{message:job.message||tr.error}));}}catch(error){pollFailures++;q('progress-text').textContent=tp(tr.err_worker,{message:error.message||tr.error});emitProgress([tp(tr.err_worker,{message:error.message||tr.error})]);if(pollFailures>=10){stopPolling();pulseHeroStatus(tp(tr.err_worker,{message:error.message||tr.error}));resetFlow(tr.cancel_done);}}};await tick();state.pollTimer=setInterval(tick,1200);}function openCreateStore(raw,name){state.createRaw=raw;createStoreInput.value=name||raw||'';createStoreModal.classList.add('is-open');setTimeout(()=>{createStoreInput.focus();createStoreInput.select();},0);}function closeCreateStore(){state.createRaw='';createStoreModal.classList.remove('is-open');}async function saveCreatedStore(){const name=createStoreInput.value.trim();if(!name){createStoreInput.focus();return;}const data=await api('?api=create_store',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});if(data.status!=='ok')return;state.stores=Array.isArray(data.stores)?data.stores:state.stores;state.selection[state.createRaw]=name;state.mappings[state.createRaw]=name;closeCreateStore();renderResolveStep();pulseHeroStatus(tr.saved_store);}async function applyMappings(){const map={};Object.keys(state.selection).forEach(raw=>{if(state.selection[raw]&&!state.skipped.has(raw))map[raw]=state.selection[raw];});try{const data=await api('?api=resolve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:state.jobId,map,skip:[...state.skipped]})});if(data.status!=='ok'){pulseHeroStatus(tp(tr.err_start,{message:data.message||tr.error}));return;}const status=await api(`?api=status&job_id=${encodeURIComponent(state.jobId)}`);if(status.status==='ok')state.report=status.job||state.report;renderResolveStep();pulseHeroStatus(tp(tr.mapping_saved,{count:data.added||0}));if((state.report&&state.report.unresolved||[]).length){emitProgress([tp(tr.mapping_saved,{count:data.added||0})]);return;}renderDatePick();if(dateUnresolvedRows().length){setStep(3);return;}renderReport();setStep(4);}catch(error){pulseHeroStatus(tp(tr.err_start,{message:error.message||tr.error}));emitProgress([tp(tr.err_start,{message:error.message||tr.error})]);}}async function cancelFlow(){if(state.canceling||!state.jobId){resetFlow(tr.cancel_done);return;}state.canceling=true;const button=q('cancel-job');button.textContent=tr.cancel_busy;button.disabled=true;try{await api('?api=cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:state.jobId})});pulseHeroStatus(tr.cancel_done);resetFlow(tr.cancel_done);emitProgress([tr.cancel_done]);}catch(error){pulseHeroStatus(tp(tr.err_start,{message:error.message||tr.error}));button.textContent=tr.cancel_job;button.disabled=false;state.canceling=false;}}async function finalizeFlow(){if(state.finalizing)return;const finishJobId=state.jobId;if(!finishJobId){emitFinished(tr.finish_done);resetFlow(tr.finish_done);return;}state.finalizing=true;const button=q('finish-btn');button.textContent=tr.finish_busy;button.disabled=true;try{const data=await api('?api=finalize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:finishJobId})});if(data.status==='ok'){pulseHeroStatus(tr.cleanup_ok);emitFinished(tr.cleanup_ok);resetFlow(tr.cleanup_ok);return;}button.textContent=tr.finish;button.disabled=false;state.finalizing=false;}catch(error){button.textContent=tr.finish;button.disabled=false;state.finalizing=false;}}async function restoreActiveJob(){await loadStores();try{const active=await api('?api=active_job');const jobId=active.job_id||'';if(!jobId)return;state.jobId=jobId;const status=await api(`?api=status&job_id=${encodeURIComponent(jobId)}`);if(status.status!=='ok')return;state.report=status.job||{};if(state.report.state==='queued'||state.report.state==='processing'){setStep(2);setRecognitionStats(state.report);pollJob(jobId);return;}if(state.report.state==='done'){renderDatePick();if((state.report.unresolved||[]).length){renderResolveStep();setStep(3);return;}if(dateUnresolvedRows().length){setStep(3);return;}renderReport();setStep(4);return;}if(state.report.state==='error'||state.report.state==='canceled'){state.jobId='';setStep(1);return;}}catch(error){}}root.addEventListener('click',event=>{const btn=event.target.closest('.ocrw-preview-delete');if(btn){const idx=Number(btn.dataset.deleteIndex);if(idx>=0&&idx<state.items.length){const item=state.items[idx];if(item.url)URL.revokeObjectURL(item.url);state.items.splice(idx,1);renderUploadStep();}}});photosInput.addEventListener('change',event=>ensureItems(event.target.files||[]));dropzone.addEventListener('dragover',event=>{event.preventDefault();dropzone.classList.add('is-drag');});dropzone.addEventListener('dragleave',()=>dropzone.classList.remove('is-drag'));dropzone.addEventListener('drop',event=>{event.preventDefault();dropzone.classList.remove('is-drag');ensureItems(event.dataTransfer.files||[]);});uploadContinue.onclick=startRecognition;q('resolve-apply').onclick=applyMappings;q('resolve-skip').onclick=()=>{renderDatePick();if(dateUnresolvedRows().length){setStep(3);return;}renderReport();setStep(4);};q('save-dates').onclick=saveDates;q('finish-btn').onclick=finalizeFlow;q('cancel-job').onclick=cancelFlow;q('create-store-save').onclick=saveCreatedStore;q('create-store-cancel').onclick=closeCreateStore;createStoreModal.addEventListener('click',event=>{if(event.target===createStoreModal)closeCreateStore();});root.addEventListener('click',event=>{if(!event.target.closest('.ocrw-store-picker'))closeStorePickers();});window.addEventListener('beforeunload',()=>{stopPolling();});setStep(1);renderUploadStep();renderFileProgress([]);restoreActiveJob();window.embeddedOcrWizard={restore:restoreActiveJob};})();
